def maps_place(key):
    return "https://www.google.com/maps/search/?api=1&query=" + quote_plus(PLACES[key][1])


def maps_route(a, b, mode="driving"):
    return ("https://www.google.com/maps/dir/?api=1&origin=" + quote_plus(PLACES[a][1])
            + "&destination=" + quote_plus(PLACES[b][1]) + "&travelmode=" + mode)


HOTEL_DINNER = "Hotel – Satvik menu pre-agreed (or Indian caterer delivering to the hotel)"
HOTEL_BREAKFAST = "Hotel – complimentary buffet (08:00–09:00)"


def T(start, end, a, b, km, mode="Coach", detail="", note="", tz=None):
    """A movement from place a to place b."""
    route_mode = "transit" if mode in ("Train", "Ferry", "Boat") else "driving"
    link = maps_place(b) if mode == "Flight" else maps_route(a, b, route_mode)
    return dict(kind="Transfer", start=start, end=end, frm=a, to=b, km=km, mode=mode,
                detail=detail or f"{mode} {PLACES[a][0]} → {PLACES[b][0]}. Bhajans, japa and sthala-purana narration on board.",
                meal_by="", note=note, tz=tz, link=link)


def V(start, end, place, kind, detail, note="", tz=None, mode="Walk"):
    return dict(kind=kind, start=start, end=end, frm="", to=place, km=0, mode=mode,
                detail=detail, meal_by="", note=note, tz=tz, link=maps_place(place))


def M(start, end, meal, place, by, detail="", note="", tz=None):
    return dict(kind=meal, start=start, end=end, frm="", to=place, km=0, mode="—",
                detail=detail, meal_by=by, note=note, tz=tz, link=maps_place(place))


